create table RB_CENT_REG (SEQ_NO VARCHAR(50) not null  ,REFERENCE VARCHAR(60) null  ,CHANNEL_SEQ_NO VARCHAR(60) null  ,SUB_SEQ_NO VARCHAR(60) null  ,ORIG_CHANNEL_SEQ_NO VARCHAR(60) null  ,ORIG_SUB_SEQ_NO VARCHAR(60) null  ,CLOSE_ACCT_IND VARCHAR(1) null  ,CENT_DEAL_TYPE VARCHAR(1) null  ,CENT_AMT DECIMAL(17,2) null  ,CCY VARCHAR(3) null  ,AMT_TYPE VARCHAR(10) null  ,CLIENT_NO VARCHAR(22) not null  ,TRAN_DATE TIMESTAMP(3) null  ,TRAN_STATUS VARCHAR(1) null  ,TRAN_TYPE VARCHAR(10) null  ,EVENT_TYPE VARCHAR(20) null  ,REVERSAL_FLAG VARCHAR(1) null  ,REVERSAL_SEQ_NO VARCHAR(60) null  ,REVERSAL_TRAN_TYPE VARCHAR(10) null  ,REVERSAL_TRAN_DATE TIMESTAMP(3) null  ,REVERSAL_USER_ID VARCHAR(30) null  ,REVERSAL_REASON VARCHAR(200) null  ,WIPE_ACCOUNT VARCHAR(1) null  ,USER_ID VARCHAR(30) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,COMPANY VARCHAR(20) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  ,CREATE_TIMESTAMP VARCHAR(26) null  , primary key(SEQ_NO,CLIENT_NO));